insert into public."programs" ("id", "org_id", "owner_coach_id", "is_org_shared", "name", "description", "goal", "periodization_model", "duration_weeks", "is_template", "created_by_id", "is_archived", "created_at", "updated_at") values
  ('1e55c530-4216-4233-a6c6-1c627847ff81','6b800303-4e48-4a7c-8ce4-9aa99d9bc5ff','d0d57a7e-8f0d-493a-979e-bf3cdf475b31','true','Block Periodization — Accumulation to Realization','Issurin-style sequencing: a hypertrophy-biased accumulation block, a heavier transmutation block, then a realization week to express the strength built.','Peak maximal strength','block','8','true','d0d57a7e-8f0d-493a-979e-bf3cdf475b31','false','2026-08-17 23:29:45.272411+00','2026-08-17 23:29:45.272411+00'),
  ('1f25e780-20b1-4b2c-bb72-df579928f7fa','d810a1ba-f39d-4656-bc4b-e16ecc58c35b','c4fb4e92-8cff-4b39-8793-be3516fb38b1','false','Linear Periodization — 4 Week Strength','Classic Matveyev progression: volume falls as intensity climbs across four weeks, closing with a deload. Best fit for novice to early-intermediate lifters.','Maximal strength','linear','4','true','c4fb4e92-8cff-4b39-8793-be3516fb38b1','false','2026-08-17 23:29:48.000864+00','2026-08-17 23:29:48.000864+00'),
  ('1fd20928-a4d1-4c37-acb1-57fd60e96b16','6b800303-4e48-4a7c-8ce4-9aa99d9bc5ff','d0d57a7e-8f0d-493a-979e-bf3cdf475b31','true','Linear Periodization — 4 Week Strength','Classic Matveyev progression: volume falls as intensity climbs across four weeks, closing with a deload. Best fit for novice to early-intermediate lifters.','Maximal strength','linear','4','true','d0d57a7e-8f0d-493a-979e-bf3cdf475b31','false','2026-08-17 23:29:44.549604+00','2026-08-17 23:29:44.549604+00'),
  ('46711486-12a3-448f-b77b-f190479e774e','6b800303-4e48-4a7c-8ce4-9aa99d9bc5ff','d0d57a7e-8f0d-493a-979e-bf3cdf475b31','true','Upper / Lower Hypertrophy — 4 Day','Four-day upper/lower split driven by double progression rather than percentages, so it works for clients who have never tested a 1RM. The default starting point for general personal-training clients.','Hypertrophy and general strength','undulating_weekly','6','true','d0d57a7e-8f0d-493a-979e-bf3cdf475b31','false','2026-08-17 23:29:47.109012+00','2026-08-17 23:29:47.109012+00'),
  ('b467fe8f-e299-4f0d-ba4d-af066e782c67','6b800303-4e48-4a7c-8ce4-9aa99d9bc5ff','d0d57a7e-8f0d-493a-979e-bf3cdf475b31','true','Conjugate — Max Effort / Dynamic Effort','Westside-style rotation. Max-effort and dynamic-effort days for upper and lower each week, so no strength quality detrains while another is being built.','Maximal and explosive strength','conjugate','3','true','d0d57a7e-8f0d-493a-979e-bf3cdf475b31','false','2026-08-17 23:29:46.67252+00','2026-08-17 23:29:46.67252+00'),
  ('defe54b5-30a0-4d37-a38b-b8f5fa4d1724','6b800303-4e48-4a7c-8ce4-9aa99d9bc5ff','d0d57a7e-8f0d-493a-979e-bf3cdf475b31','true','Daily Undulating Periodization — 3 Day','Heavy, moderate and light days inside the same week, so strength, hypertrophy and power qualities are all trained without waiting for a block to end. Strong fit for intermediates.','Concurrent strength and hypertrophy','undulating_daily','4','true','d0d57a7e-8f0d-493a-979e-bf3cdf475b31','false','2026-08-17 23:29:46.165761+00','2026-08-17 23:29:46.165761+00');
