-- ===================================================================
-- HEME — Block 2 of 2: seed data
--
-- Run AFTER Block 1. Creates three coach logins, the 213-exercise global
-- library, a demo roster, and five program templates.
--
-- Fixture shape — deliberately adversarial, so isolation is observable:
--   Org A "HEME Performance"  ── Alex Reid  (Priya, Marcus)
--                             └─ Jordan Six (Aisha)     <- same org, other coach
--   Org B "Northside Strength" ── Sam Okafor (Tom)       <- separate tenant
--
-- Sign in as Alex then Jordan: same organisation, and the athlete lists do
-- not overlap. That is the whole point of the RLS layer.
--
-- Logins (all password: heme-demo-1234):
--   a1@heme.test     Alex Reid
--   a2@heme.test     Jordan Six
--   b1@heme.test     Sam Okafor
-- ===================================================================

begin;

-- ===================================================================
-- 1. Auth identities
--
-- Inserted directly because the Admin API is not being used here. The
-- password is bcrypt-hashed with pgcrypto, and an auth.identities row is
-- added because GoTrue requires one for email/password sign-in.
--
-- The empty strings on the token columns are load-bearing. GoTrue maps each
-- of them to a Go string, which cannot hold NULL, while Supabase declares
-- them nullable with no default. Omit them here and they store NULL, and
-- then every sign-in fails with HTTP 500:
--
--   sql: Scan error on column index 3, name "confirmation_token":
--   converting NULL to string is unsupported
--
-- The row looks perfect in SQL when this happens — the password hash
-- verifies, the email is confirmed, the identity row exists — because the
-- fault is a type mismatch in the reader, not bad data. It also breaks the
-- Admin API, so the usual escape hatch of resetting the password through
-- Supabase is closed too.
-- ===================================================================

  instance_id, id, aud, role, email, encrypted_password,
  email_confirmed_at, created_at, updated_at,
  raw_app_meta_data, raw_user_meta_data, is_sso_user, is_anonymous,
  confirmation_token, recovery_token, email_change,
  email_change_token_new, email_change_token_current,
  phone_change, phone_change_token, reauthentication_token
) values
  ('00000000-0000-0000-0000-000000000000', 'd0d57a7e-8f0d-493a-979e-bf3cdf475b31', 'authenticated', 'authenticated',
   'a1@heme.test', extensions.crypt('heme-demo-1234', extensions.gen_salt('bf', 10)),
   now(), now(), now(),
   '{"provider":"email","providers":["email"]}'::jsonb, '{"name":"Alex Reid","org_name":null}'::jsonb, false, false,
   '', '', '', '', '', '', '', ''),
  ('00000000-0000-0000-0000-000000000000', '1e11509c-0e2b-4890-bb21-b047686d1566', 'authenticated', 'authenticated',
   'a2@heme.test', extensions.crypt('heme-demo-1234', extensions.gen_salt('bf', 10)),
   now(), now(), now(),
   '{"provider":"email","providers":["email"]}'::jsonb, '{"name":"Jordan Six","org_name":null}'::jsonb, false, false,
   '', '', '', '', '', '', '', ''),
  ('00000000-0000-0000-0000-000000000000', 'c4fb4e92-8cff-4b39-8793-be3516fb38b1', 'authenticated', 'authenticated',
   'b1@heme.test', extensions.crypt('heme-demo-1234', extensions.gen_salt('bf', 10)),
   now(), now(), now(),
   '{"provider":"email","providers":["email"]}'::jsonb, '{"name":"Sam Okafor","org_name":null}'::jsonb, false, false,
   '', '', '', '', '', '', '', '')
on conflict (id) do nothing;

  id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at
) values
  (extensions.gen_random_uuid(), 'd0d57a7e-8f0d-493a-979e-bf3cdf475b31', 'd0d57a7e-8f0d-493a-979e-bf3cdf475b31',
   jsonb_build_object('sub', 'd0d57a7e-8f0d-493a-979e-bf3cdf475b31', 'email', 'a1@heme.test', 'email_verified', true, 'phone_verified', false),
   'email', now(), now(), now()),
  (extensions.gen_random_uuid(), '1e11509c-0e2b-4890-bb21-b047686d1566', '1e11509c-0e2b-4890-bb21-b047686d1566',
   jsonb_build_object('sub', '1e11509c-0e2b-4890-bb21-b047686d1566', 'email', 'a2@heme.test', 'email_verified', true, 'phone_verified', false),
   'email', now(), now(), now()),
  (extensions.gen_random_uuid(), 'c4fb4e92-8cff-4b39-8793-be3516fb38b1', 'c4fb4e92-8cff-4b39-8793-be3516fb38b1',
   jsonb_build_object('sub', 'c4fb4e92-8cff-4b39-8793-be3516fb38b1', 'email', 'b1@heme.test', 'email_verified', true, 'phone_verified', false),
   'email', now(), now(), now())
on conflict do nothing;

-- The signup trigger just created one organisation and profile per coach.
-- Clear them: the rows below carry fixed ids that the rest of the seed
-- references, and the two coaches in Org A must share one organisation.
delete from public.users;
delete from public.organizations;

