-- ===================================================================
-- Verification
-- ===================================================================

-- Expect: 213 global exercises, 3 coaches, 2 organisations, 4 athletes,
-- 6 programs, 915 prescribed sets.
select
  (select count(*) from public.exercises where org_id is null) as global_exercises,
  (select count(*) from public.users)                          as coaches,
  (select count(*) from public.organizations)                  as organizations,
  (select count(*) from public.athletes)                        as athletes,
  (select count(*) from public.programs)                       as programs,
  (select count(*) from public.prescribed_sets)                as prescribed_sets;

-- The isolation check. Expect exactly one row per coach, and note that the
-- two "HEME Performance" coaches own different athletes.
select u.email, o.name as organisation, count(a.id) as own_athletes,
       string_agg(a.first_name || ' ' || a.last_name, ', ' order by a.first_name) as roster
from public.users u
join public.organizations o on o.id = u.org_id
left join public.athletes a on a.owner_coach_id = u.id
group by u.email, o.name
order by o.name, u.email;
